//! Temporary timing probe over a saved RL actor and the actual standing trainer.
#[expect(dead_code, unused_imports, reason = "Only the actual collector and model are timed.")]
#[path = "../examples/robots/learning/mod.rs"]
mod learning;
#[expect(dead_code, reason = "The profile shares the complete standing module.")]
#[path = "../examples/robots/standing/mod.rs"]
mod standing;

#[test]
fn profile_actual_standing_training() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("runs/droid-standing/seed13-warm-start-20261010/standing-660.mpk");
    let bytes = std::fs::read(&path).expect("preserved RL actor and critic");
    let metadata = std::fs::read(path.with_extension("json")).expect("saved provenance");
    standing::checkpoint::Record::for_bytes(&bytes, &metadata).expect("digest matches");
    let mut agent = standing::model::warm_start(17, bytes).expect("valid same architecture");
    let mut batch = standing::batch(17, &agent.policy());
    for update in 1..=5 {
        let started = std::time::Instant::now();
        let policy = agent.policy();
        let snapshot_us = started.elapsed().as_micros();
        let started = std::time::Instant::now();
        let sequences = batch.collect(&policy).expect("512 physical RL transitions");
        let collect_us = started.elapsed().as_micros();
        let started = std::time::Instant::now();
        let metrics = agent.update(&sequences).expect("actual PPO update");
        let optimize_us = started.elapsed().as_micros();
        assert_eq!(metrics.valid_samples, 512);
        println!("PROFILE update={update} snapshot_us={snapshot_us} collect_us={collect_us} optimize_us={optimize_us}");
    }
}
